import React, { useState } from 'react';
import './UploadFile.css';

const UploadFile = () => {
  const [testCases, setTestCases] = useState([]);
  const [uploadProgress, setUploadProgress] = useState({});
  const [isDrop, setIsDrop] = useState(false);

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDrop(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDrop(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDrop(false);
    const files = Array.from(e.dataTransfer.files);
    handleFiles(files);
  };

  const handleFileInput = (e) => {
    const files = Array.from(e.target.files);
    handleFiles(files);
  };

  const handleFiles = (files) => {
    files.forEach(file => {
      const testCase = {
        id: `test-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        name: file.name,
        size: formatFileSize(file.size),
        status: 'uploading'
      };

      setTestCases(prev => [...prev, testCase]);
      simulateUpload(testCase.id);
    });
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 KB';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  const simulateUpload = (id) => {
    let progress = 0;
    setUploadProgress(prev => ({ ...prev, [id]: 0 }));

    const interval = setInterval(() => {
      progress += 10;
      setUploadProgress(prev => ({ ...prev, [id]: progress }));

      if (progress >= 100) {
        clearInterval(interval);
        setTestCases(prev =>
          prev.map(tc =>
            tc.id === id ? { ...tc, status: 'completed' } : tc
          )
        );
      }
    }, 500);
  };

  return (
    <div className="swagger-container">
      <div className="swagger-header">
        <h2 className="swagger-title">Upload Test Cases</h2>
        <p className="swagger-subtitle">Drag and drop your test case files here</p>
      </div>

      <div
        className={`upload-area ${isDrop ? 'drag-active' : ''}`}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        {isDrop ? (
          <div className="drop-message">Drop files here!</div>
        ) : (
          <div className="features-grid">
            <div className="upload-icon-container">
              <svg className="upload-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
              </svg>
            </div>
            <p>Click to browse or drag and drop your files</p>
            <input
              type="file"
              multiple
              onChange={handleFileInput}
              className="file-input"
              accept=".json,.yaml,.yml"
            />
          </div>
        )}
      </div>

      <div className="test-cases-list">
        {testCases.map(testCase => (
          <div key={testCase.id} className="test-case-item">
            <div className="test-case-info">
              <span className="test-case-name">{testCase.name}</span>
              <span className="test-case-size">{testCase.size}</span>
            </div>
            <div className="progress-bar">
              <div
                className="progress"
                style={{ width: `${uploadProgress[testCase.id] || 0}%` }}
              />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default UploadFile;
